// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initial deposit via fallback
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "fallback failed");

        // Send 1 wei to owner via sendMoney
        address owner = c.owner();
        vm.prank(owner);
        c.sendMoney(owner, 1 wei);

        // Now call withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // Assert the contract balance after withdrawAll: reference leaves 1 ether - 1 wei, mutant leaves 0
        assertTrue(address(c).balance == 1 ether - 1 wei);
    }
}

